pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
        c.SetLogFile(address(new LogView()));
        c.Initialized();
    }

    function testFuzz_property(uint256 amount, address actor, uint256 lockTime) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1, 100 ether);
        lockTime = bound(lockTime, 0, 365 days);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(lockTime);

        (address sender, uint256 val, string memory data) = c.Log(0);
        LogView lv = LogView(cAddress());
        (, , uint256 loggedVal, ) = lv.History(0);
        assertTrue(loggedVal == amount && keccak256(bytes(data)) == keccak256(bytes("Put")));
    }

    function cAddress() internal view returns (address) {
        return address(c);
    }
}

contract LogView is C.LogFallback {}

