pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log lg;

    function setUp() public {
        c = new C();
        lg = new Log();
        c.SetLogFile(address(lg));
        c.Initialized();
    }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, type(uint128).max);

        vm.deal(actor, amount);
        uint256 balBefore = address(c).balance;
        vm.prank(actor);
        c.Put{value: amount}(0);

        (, , uint256 val, ) = lg.History(lg.History.length() - 1);
        assertTrue(val == address(c).balance - balBefore);
    }
}

